    fun rmse(errors: List<Double>): Double {
        if(errors.isEmpty())return Double.NaN;
        var sum=0.0;
        for(e in errors)sum+=e*e;
        return sqrt(sum/errors.size)
    }
    fun real(value: Double): String {
        if(value.isNaN())return "-";
        val text=String.format(Locale.ROOT,"%.4f",value);
        return if(text=="-0.0000")"0.0000" else text
    }
